        if(c.world==null||c.player==null){if(System.nanoTime()-start>180_000_000_000L)finish(c,"FAILED: world timeout");return;}ticks++;if(c.currentScreen!=null)c.setScreen(null);
        if(ticks==5){Class<?> config=ChatRuntimeSmoke.protectedClass("com.batclient.HudConfig");update=method(config,boolean.class,String.class,String.class,boolean.class);loot=ChatRuntimeSmoke.protectedClass("com.batclient.LootBeams");free=ChatRuntimeSmoke.protectedClass("com.batclient.Freelook");active=method(free,boolean.class);c.player.setYaw(0);c.player.setPitch(5);
            patch("lootbeams","{\"en\":true,\"set\":{\"filter\":\"All\",\"range\":24,\"limit\":8,\"minimum\":1,\"rarityColors\":false,\"color\":\"#FF00FFFF\",\"labels\":true}}");
            add(c,new ItemStack(Items.DIAMOND,3),-2,9);add(c,new ItemStack(Items.COBBLESTONE,64),0,10);add(c,new ItemStack(Items.ENCHANTED_GOLDEN_APPLE),2,9);
            var accept=method(loot,boolean.class,ItemStack.class,String.class,int.class);check((boolean)accept.invoke(null,new ItemStack(Items.DIAMOND),"Valuables",1),"diamonds included in valuables");check(!(boolean)accept.invoke(null,new ItemStack(Items.COBBLESTONE),"Valuables",1),"common stone excluded from valuables");check(!(boolean)accept.invoke(null,new ItemStack(Items.DIAMOND),"Rare",1),"rare filter uses actual rarity rather than item value");check(!(boolean)accept.invoke(null,new ItemStack(Items.DIAMOND,2),"All",3),"minimum stack count enforced");
        }
